public void generateCompleteBipartiteGraph(Graph<V,E> target, Map<String, V> resultMap) {
    // Generate a new graph with the same vertex and edge types as the input graph
    Graph<V,E> completeGraph = new Graph<>(target.getVertexType(), target.getEdgeType());

    // Initialize the vertex sets for the two sides of the bipartite graph
    Set<V> leftVertices = new HashSet<>();
    Set<V> rightVertices = new HashSet<>();
    V maxLabel = null;

    // Iterate over the input graph and initialize the vertex sets
    for (V vertex : target.getVertices()) {
        if (maxLabel == null || vertex.getLabel().compareTo(maxLabel) > 0) {
            maxLabel = vertex.getLabel();
        }
        leftVertices.add(vertex);
        rightVertices.add(vertex);
    }

    // Add edges between vertices with labels at most twice the maximum label size
    for (V leftVertex : leftVertices) {
        for (V rightVertex : rightVertices) {
            if (leftVertex.getLabel().compareTo(rightVertex.getLabel()) <= 2 * Math.abs(maxLabel) - 1) {
                completeGraph.addEdge(leftVertex, rightVertex);
            }
        }
    }

    // Add the vertices and edges to the result map
    for (V vertex : completeGraph.getVertices()) {
        resultMap.put(vertex.getLabel(), vertex);
    }
    for (E edge : completeGraph.getEdges()) {
        resultMap.put(edge.toString(), edge);
    }
