public int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int encodedLength = encodedLength(message, schema);
    if (encodedLength == 0) {
        return 0;
    }

    int size = 0;
    // allocate space for the length field
    size += buffer.ensureCapacity(encodedLength);
    buffer.position(size);
    // encode the data
    encode(message, schema, buffer);
    size += buffer.position();
    // check for errors
    buffer.rewind();
    assert buffer.ensureCapacity(0) == 0 : "UnexpectedBufferOverflow: buffer size is " + buffer.capacity();
    // write to the output stream
    out.write(buffer.nioBuffer());
    return size;
}

