public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if the generic type is parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the generic type definition
    ParameterizedType genericTypeDefinition = (ParameterizedType) genericType;

    // Get the type variables for the target type
    TypeVariable<?>[] typeVariables = targetType.getTypeParameters();

    // Resolve the type arguments for the generic type definition
    Type[] typeArguments = resolveGenericTypeArguments(genericTypeDefinition, targetType);

    // Create an array to store the resolved arguments
    Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];

    // Resolve the arguments
    for (int i = 0; i < typeArguments.length; i++) {
        // Get the type argument
        Type typeArgument = typeArguments[i];

        // Get the corresponding type variable
        TypeVariable<?> typeVariable = typeVariables[i];

        // Resolve the type argument
        Class<?> resolvedArgument = resolveTypeArgument(typeArgument, typeVariable);

        // Add the resolved argument to the array
        resolvedArguments[i] = resolvedArgument;
    }

    return resolvedArguments;
}

