            data[length+i] = 0;
        }
        length += byteLength;
        return this;
    } else {
        int actualLength = byteArrayValue.length < byteOffset? 0 : 1 + byteArrayValue.length - byteOffset;
        if (length + actualLength > data.length) {
            enlarge(actualLength);
        }
        for (int i = 0; i < byteLength; i++) {
            data[length+i] = byteArrayValue[i + byteOffset];
        }
        length += byteLength;
        return this;
    }
}

