    // check if the session is null
    if (session == null) {
        throw new NullPointerException("session cannot be null");
    }
    // check if the buffer is null
    if (lb == null) {
        throw new NullPointerException("buffer cannot be null");
    }
    // write the string to the buffer with the specified encoding
    final boolean isUtf8 = session.getConfig().isUtf8;
    final int result = writeString(str, isUtf8, lb);
    // check if the result is positive
    if (result < 0) {
        throw new IOException("unknown error");
    }
    // return the updated buffer
    return lb;
}

void writeUTF8(String str, WriteSession session, LinkedBuffer lb) {
    // Get the number of bytes needed to represent the string in UTF-8
    int byteCount = lb.getByteBufferSize();
    // Make sure the LinkedBuffer has enough capacity to hold the UTF-8 bytes
    if (byteCount < str.length()) {
        byteCount = str.length();
    }
    // Put the bytes into the LinkedBuffer
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c >= 0x010000) {
            // out-of-range characters are replaced with the Unicode replacement character
            byteCount += 3;
        } else if (c <= 0x007F) {
            lb.put((byte) c);
        } else {
            lb.put((byte) (0xC0 | c >> 6));
            lb.put((byte) (0x80 | c & 0x3F));
        }
    }
    // Adjust the LinkedBuffer's capacity to reflect the actual number of bytes written
    lb.setByteBufferSize(byteCount);
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
        if (str == null) {
            throw new IllegalArgumentException("str must not be null");
        }
        if (session == null) {
            throw new IllegalArgumentException("session must not be null");
        }
        if (lb == null) {
            throw new IllegalArgumentException("lb must not be null");
        }

        // byte[] byteArray = str.toUtf8()
        byte[] byteArray = new byte[str.length()];
        for (int i = 0; i < str.length(); i++) {
            if (Character.isHighSurrogate(str.charAt(i)) || Character.isLowSurrogate(str.charAt(i))) {
                byteArray[i] = (byte) Character.toCodePoint(str.charAt(i), str.charAt(i + 1));
            } else {
                byteArray[i] = (byte) str.charAt(i); 
            }
        }

        // write the length of the utf-8 string
        synchronized (lb) {
            lb.addUTF8(byteArray.length);     
        }

        // write the utf-8 bytes to the linked buffer        
        for (int i = 0; i < byteArray.length; i++) {
            synchronized (lb) {
                lb.addByte(byteArray[i]);
            }
        }

        return lb;
    }

