private static String substituteVars(String value, Properties props) {
    String result = value;
    Pattern varPat = Pattern.compile("\\$\\{([a-zA-Z_][a-zA-Z0-9_]*)\\}");
    Matcher matcher = varPat.matcher(result);
    while (matcher.find()) {
        String key = matcher.group(1);
        String replacement = props.getProperty(key);
        if (replacement == null) {
            replacement = "${" + key + "}";
        }
        result = result.replace(matcher.group(0), replacement);
    }
    return result;
}

