    if (fileBuffer.length - nextByte < numBytes) {
        return null;
    }

    // Get the next byte
    byte b = fileBuffer[nextByte++];

    // Peek ahead to see if EOB or EOLN is reached
    boolean eof = false;
    boolean atEoln = true;
    while (atEoln && !eof) {
        b = fileBuffer[nextByte++];
        if (b == EOB) {
            eof = true;
        } else if (b == EOLN) {
            atEoln = false;
        }
    }

    // Return the next byte
    return b;
