                        StackMapTableEntry entry = new StackMapTableEntry(uninitializedType.getObjectTypeName(), uninitializedType.getOffset());
                        stackMapTableEntries.add(entry);
                    }
                }
            }
        } else if (frame instanceof ImplicitStackMapFrame) {
            ImplicitStackMapFrame implicitFrame = (ImplicitStackMapFrame) frame;
            VerificationTypeInfo implicitType = implicitFrame.getImplicitType();
            if (implicitType.isInternalType()) {
