public void readFrom(final InputStream in) throws IOException {
    // Clear the buffer
    byte[] buffer = new byte[in.available()];
    in.read(buffer);

    // Check if the length of the buffer is sufficient
    if (buffer.length < MIN_READ_SIZE) {
        throw new IOException("Buffer is too small to read from the input stream.");
    }

    // Reset the read pointer to the start of the byte array
    this.bufferPosition = 0;

    // Fill the buffer with the supplied byte stream
    int read = 0;
    while (read < buffer.length) {
        int n = in.read(buffer, read, buffer.length - read);
        if (n < 0) {
            break;
        }
        read += n;
    }

    // Check if the entire buffer has been filled
    if (read < buffer.length) {
        throw new IOException("InputStream did not contain enough bytes to fill the buffer.");
    }
}

