public static int nextPrime(int desiredCapacity) {
    // First, check if the input is valid and if it is >= 1000.
    if (desiredCapacity < 1000) {
        throw new IllegalArgumentException("desiredCapacity must be >= 1000");
    }

    // Find the next prime number that is within 11% of the desiredCapacity.
    for (int prime = desiredCapacity; prime < desiredCapacity * 1.1; prime++) {
        if (isPrime(prime)) {
            return prime;
        }
    }

