public static int nextPrime(int desiredCapacity) {
    int[] primeCapacities = {11, 23, 47, 97, 197, 397, 797, 1597, 3197, 6397, 12797, 25597, 1319, 2561, 5121, 10241, 20481, 40961, 8191, 16381, 32771, 65521};
    if (desiredCapacity < primeCapacities[0]) {
        return primeCapacities[0];
    } else if (desiredCapacity > primeCapacities[primeCapacities.length - 1]) {
        return primeCapacities[primeCapacities.length - 1];
    }

    int closestPrime = primeCapacities[0];
    int diff = Integer.MAX_VALUE;
    for (int i = 1; i < primeCapacities.length; i++) {
        int currentDiff = Math.abs(desiredCapacity - primeCapacities[i]);
        if (currentDiff < diff) {
            closestPrime = primeCapacities[i];
            diff = currentDiff;
        }
    }

    return closestPrime;
}

