private GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    GraphPath<V, E> path = new GraphPath<>(graph);
    List<V> vertices = new ArrayList<>(graph.vertexSet());
    List<E> reversedEdges = new ArrayList<>();

    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        path.add(source, target);
        if (reversedEdges.isEmpty() || !reversedEdges.get(reversedEdges.size() - 1).equals(edge)) {
            reversedEdges.add(edge);
        }
    }

    for (int i = reversedEdges.size() - 1; i >= 0; i--) {
        E edge = reversedEdges.get(i);
        path.add(graph.getEdgeTarget(edge), graph.getEdgeSource(edge));
    }

    return path;
}

