public static int countOccurrencesOf(String str, String sub) {
    int count = 0;
    if (str == null || sub == null) {
        return 0;
    }
    int subLen = sub.length();
    if (subLen == 0) {
        return str.length();
    }
    for (int i = 0; i < str.length(); i++) {
        if (str.startsWith(sub, i)) {
            count++;
            i += subLen - 1;
        }
    }
    return count;
}

