public static String base64Decode(final String s) {
    int length = s.length(), padding = 0, lengthAfterDecoding = 0;
    byte[] bytes = new byte[length / 4 * 3];

    for (int i = 0; i < length; i++) {
        char c = s.charAt(i);
        if (c == '=') {
            padding++;
        } else {
            bytes[i] = (byte) ((byte) (c -= 43) % 255);
        }
    }

    if (padding > 0) {
        lengthAfterDecoding = length - padding;
        if (padding == 1 && bytes[lengthAfterDecoding - 1] == 0) {
            lengthAfterDecoding--;
        } else if (padding > 1 && bytes[lengthAfterDecoding - 1] == 0 && bytes[lengthAfterDecoding - 2] == 0) {
            lengthAfterDecoding -= 2;
        }
    } else {
        lengthAfterDecoding = length;
    }

    return new String(bytes, 0, lengthAfterDecoding, StandardCharsets.UTF_8);
}

