private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.getEdges()) {
        List<Pair<Integer, Integer>> separatorList = new ArrayList<>();
        for (Integer v : graph.getNeighbors(e.getSource())) {
            if (v != e.getTarget()) {
                separatorList.add(new Pair<>(e.getSource(), v));
            }
        }
        for (Integer v : graph.getNeighbors(e.getTarget())) {
            if (v != e.getSource()) {
                separatorList.add(new Pair<>(e.getTarget(), v));
            }
        }
        globalSeparatorList.add(new Pair<>(separatorList, e));
    }
    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = new ArrayList<>();
    for (E edge : graph.getEdges()) {
        List<Pair<Integer,Integer>> minimalSeparators = new ArrayList<>();
        for (V vertex : graph.getNeighbors(edge.getSrc())) {
            List<Pair<Integer,Integer>> separators = new ArrayList<>();
            for (V neighbor : graph.getNeighbors(vertex)) {
                if (neighbor == edge.getDst()) {
                    separators.add(new Pair<>(vertex.getId(), neighbor.getId()));
                }
            }
            minimalSeparators.addAll(separators);
        }
        separatorList.add(new Pair<>(minimalSeparators, edge));
    }
    return separatorList;
}

