    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E edge : graph.getEdges()) {
        List<Pair<List<Pair<Integer, Integer>>, E>> edgeSeparatorList = computeEdgeSeparatorList(edge);
        globalSeparatorList.addAll(edgeSeparatorList);
    }
