public String buildContentRange(String ... parameters) {
    if (parameters.length != 2) {
        throw new IllegalArgumentException("Invalid number of parameters. Expected 2 but got " + parameters.length);
    }

    String unit = parameters[0];
    String rangeEnd = parameters[1];

    if (!unit.equals(BYTES) && !unit.equals(UNITS)) {
        throw new IllegalArgumentException("Invalid unit value. Expected 'bytes' or 'units' but got " + unit);
    }

    int lastBytePosition = rangeEnd.lastIndexOf("/");
    if (lastBytePosition == -1) {
        throw new IllegalArgumentException("Invalid range-end value. Expected 'Last-Byte-Pos'/'Entity-Length' format but got " + rangeEnd);
    }

    String lastBytePos = rangeEnd.substring(0, lastBytePosition);
    String entityLength = rangeEnd.substring(1 + lastBytePosition);

    try {
        long lastBytePosLong = Long.parseLong(lastBytePos);
        long entityLengthLong = Long.parseLong(entityLength);

        if (lastBytePosLong < 0) {
            throw new IllegalArgumentException("Invalid last-byte-pos value. Expected non-negative integer but got " + lastBytePosLong);
        }

        if (entityLengthLong <= 0) {
            throw new IllegalArgumentException("Invalid entity length. Expected positive integer but got " + entityLengthLong);
        }

        return String.format("%s %s-%s/%s", unit, lastBytePos, lastBytePos, entityLength);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Invalid input format for range-end or entity-length", e);
    }
}

