public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = Files.newBufferedReader(file.toPath())) {
        String line = reader.readLine();
        while (line != null) {
            String[] splitLine = line.split(",");
            ProfileAnalyzeTimeRange range = timeRanges.stream().filter(t -> t.getStartMillis() <= Long.parseLong(splitLine[0]) && t.getEndMillis() >= Long.parseLong(splitLine[0])).findFirst().orElseThrow(() -> new IOException("No time range found for timestamp"));
            snapshots.add(new ThreadSnapshot(Long.parseLong(splitLine[0]), Long.parseLong(splitLine[1]), Long.parseLong(splitLine[2]), range));
            line = reader.readLine();
        }
    } catch (IOException e) {
        throw new IOException("Error while reading from file", e);
    }
    return snapshots;
}

public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("//")) {
                continue;
            }
            String[] tokens = line.split(" ");
            long timestamp = Long.parseLong(tokens[0]);
            long cpuUsage = Long.parseLong(tokens[1]);
            long count = Long.parseLong(tokens[2]);
            long totalUserTime = Long.parseLong(tokens[3]);
            long totalBlockedTime = Long.parseLong(tokens[4]);
            long totalWaitedTime = Long.parseLong(tokens[5]);
            long totalSleepTime = Long.parseLong(tokens[6]);
            long totalStoppedTime = Long.parseLong(tokens[7]);
            long totalRunTime = Long.parseLong(tokens[8]);
            long totalFreeTime = Long.parseLong(tokens[9]);
            String methodName = tokens[10];
            long classId = Long.parseLong(tokens[11]);
            String threadName = tokens[12];
            long threadId = Long.parseLong(tokens[13]);
            long sampleEvent = Long.parseLong(tokens[14]);
            boolean isRunnable = tokens[15];
            String className = tokens[16];
            String nativeMethodSignature = tokens[17];
            long nativeMethodId = Long.parseLong(tokens[18]);
            long javaEvent = Long.parseLong(tokens[19]);
            String exceptionClassName = tokens[20];
            long exceptionClassloader = Long.parseLong(tokens[21]);
            String exceptionMessage = tokens[22];
            String stackTrace = tokens[23];
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timestamp >= timeRange.from && timestamp <= timeRange.to) {
                    ThreadSnapshot threadSnapshot = new ThreadSnapshot();
                    threadSnapshot.timestamp = timestamp;
                    threadSnapshot.cpuUsage = cpuUsage;
                    threadSnapshot.count = count;
                    threadSnapshot.totalUserTime = totalUserTime;
                    threadSnapshot.totalBlockedTime = totalBlockedTime;
                    threadSnapshot.totalWaitedTime = totalWaitedTime;
                    threadSnapshot.totalSleepTime = totalSleepTime;
                    threadSnapshot.totalStoppedTime = totalStoppedTime;
                    threadSnapshot.totalRunTime = totalRunTime;
                    threadSnapshot.totalFreeTime = totalFreeTime;
                    threadSnapshot.methodName = methodName;
                    threadSnapshot.classId = classId;
                    threadSnapshot.threadName = threadName;
                    threadSnapshot.threadId = threadId;
                    threadSnapshot.sampleEvent = sampleEvent;
                    threadSnapshot.isRunnable = isRunnable;
                    threadSnapshot.className = className;
                    threadSnapshot.nativeMethodSignature = nativeMethodSignature;
                    threadSnapshot.nativeMethodId = nativeMethodId;
                    threadSnapshot.javaEvent = javaEvent;
                    threadSnapshot.exceptionClassName = exceptionClassName;
                    threadSnapshot.exceptionClassloader = exceptionClassloader;
                    threadSnapshot.exceptionMessage = exceptionMessage;
                    threadSnapshot.stackTrace = stackTrace;
                    threadSnapshots.add(threadSnapshot);
                    break;
                }
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(file)))) {
            String line;
            while ((line = br.readLine()) != null) {
                // parse each line of the file to extract the thread snapshot
                ThreadSnapshot snapshot = parseThreadSnapshot(line);
                if (snapshot != null && withinTimeRange(snapshot, timeRange)) {
                    threadSnapshots.add(snapshot);
                }
            }
        }
    }
    return threadSnapshots;
}

